import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"自研或引入组件库","description":"","frontmatter":{"title":"自研或引入组件库","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/ui/component-library.md","filePath":"frontend/decisions/ui/component-library.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/ui/component-library.md"};function o(l,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="自研或引入组件库" tabindex="-1">自研或引入组件库 <a class="header-anchor" href="#自研或引入组件库" aria-label="Permalink to &quot;自研或引入组件库&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>组件库决策比通用“自研或采购”多一层：组件必须与框架、设计语言、无障碍、表单、SSR 和产品交互长期协作。直接使用成熟库、在其上建立适配层、采用无样式原语或完全自研，承担的控制权和责任不同。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>引入组件库能快速获得对话框、选择器和表格等能力，但深度定制可能受 DOM、样式和状态模型限制。自研能贴合品牌，也会承担键盘、焦点、国际化、浏览器和持续测试。</p><p>组件库不是设计系统本身；前者交付可复用代码，后者还包含令牌、设计规则、治理和跨职能协作。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-准入硬约束" tabindex="-1">2.1 准入硬约束 <a class="header-anchor" href="#_2-1-准入硬约束" aria-label="Permalink to &quot;2.1 准入硬约束&quot;">​</a></h3><ul><li>支持已选框架、SSR、浏览器和 TypeScript 基线；</li><li>许可证允许产品分发，依赖供应链可审计；</li><li>核心交互满足目标无障碍等级并可在真实读屏器中验证；</li><li>主题和品牌定制无需依赖不稳定内部 DOM；</li><li>安全问题和破坏性升级有可接受的响应与迁移路径。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较组件覆盖、交互质量、无障碍、主题、API 一致性、表单集成、包体积、按需加载、文档、维护活跃度、升级、支持和替换成本。功能数量不应高于实际验收需求。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-直接采用完整组件库" tabindex="-1">3.1 直接采用完整组件库 <a class="header-anchor" href="#_3-1-直接采用完整组件库" aria-label="Permalink to &quot;3.1 直接采用完整组件库&quot;">​</a></h3><p>适合品牌定制有限、交付时间紧和常规业务组件占主导的产品。上手快，但页面会较深依赖库的 Props、DOM 和主题系统。</p><h3 id="_3-2-组件库加内部适配层" tabindex="-1">3.2 组件库加内部适配层 <a class="header-anchor" href="#_3-2-组件库加内部适配层" aria-label="Permalink to &quot;3.2 组件库加内部适配层&quot;">​</a></h3><p>对外暴露公司的命名、令牌和少量稳定组件，内部使用第三方实现。适合希望控制消费契约又不自研底层交互的团队。适配层必须薄，不能复制所有第三方 Props。</p><h3 id="_3-3-无样式或低样式原语" tabindex="-1">3.3 无样式或低样式原语 <a class="header-anchor" href="#_3-3-无样式或低样式原语" aria-label="Permalink to &quot;3.3 无样式或低样式原语&quot;">​</a></h3><p>复用焦点、键盘和状态逻辑，视觉完全由团队实现。适合品牌要求高且有 CSS、设计和无障碍能力的团队；交付视觉组件仍需较大投入。</p><h3 id="_3-4-完全自研" tabindex="-1">3.4 完全自研 <a class="header-anchor" href="#_3-4-完全自研" aria-label="Permalink to &quot;3.4 完全自研&quot;">​</a></h3><p>适合交互确有差异化、硬约束排除外部方案，或平台规模足以承担长期团队的场景。自研范围应从高频基础组件和真实业务需求增长，不追求一次覆盖所有控件。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 6 个 Vue 3 中后台产品、40 名开发者、两个品牌主题，12 周内需要统一表单、表格和弹层；设计团队 3 人，没有专职无障碍工程师。</p><table tabindex="0"><thead><tr><th>维度</th><th>完整库直用</th><th>完整库 + 适配层</th><th>无样式原语</th><th>完全自研</th></tr></thead><tbody><tr><td>首期速度</td><td>最快</td><td>快</td><td>中至慢</td><td>最慢</td></tr><tr><td>品牌控制</td><td>中</td><td>中至高</td><td>高</td><td>最高</td></tr><tr><td>无障碍基础</td><td>依库</td><td>依库并可补偿</td><td>原语提供部分</td><td>全部自担</td></tr><tr><td>API 控制</td><td>低</td><td>高</td><td>高</td><td>最高</td></tr><tr><td>升级成本</td><td>消费者直接承担</td><td>适配层集中吸收</td><td>内部视觉层承担</td><td>全部内部承担</td></tr><tr><td>团队匹配</td><td>好</td><td>好</td><td>当前能力不足</td><td>当前能力不足</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>推荐选择通过原型与无障碍验收的成熟 Vue 组件库，并建立薄适配层。首期只封装按钮、输入、选择器、对话框、表格和消息等高频组件；业务组件仍由产品域维护。</p><p>适配层公开公司的设计令牌、尺寸、状态和事件，不透传所有第三方属性。确有特殊需求时，先补充组合槽位；若需要访问库内部 DOM 才能实现，应记录为退出风险。</p><p>对品牌展示型页面，可在局部使用无样式原语或自研，不要求整个组织只有一种实现来源。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>团队获得成熟交互和较快统一，同时接受第三方升级、部分 DOM 限制和双层排障。组件平台负责依赖升级、回归、迁移指南和例外审查，业务团队不直接锁定任意第三方 API。</p><p>适配层过厚会形成“再造一个组件库”。应跟踪包装代码比例、透传 Props 和例外数量。若第三方库被替换，适配层只能减少常用组件的消费者改动，不能保证零成本。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>独特品牌交互是产品核心且成熟库无法定制时，直接采用会积累覆盖样式债务。</li><li>不要仅看演示站组件数量，必须验证真实表单、焦点、SSR 和国际化。</li><li>不要为“避免锁定”而从零实现所有可访问性交互。</li><li>适配层不应无条件透传第三方全部 Props。</li><li>单个产品的小规模控件不一定需要组织级组件库。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>六个 Vue 后台如何获得一致基础组件</td></tr><tr><td>硬约束</td><td>12 周；双品牌；无障碍 AA；SSR；许可证和安全准入</td></tr><tr><td>候选</td><td>直用完整库、适配层、无样式原语、完全自研</td></tr><tr><td>决定</td><td>成熟库 + 薄适配层，展示页面允许局部例外</td></tr><tr><td>首期范围</td><td>7 类高频基础组件，不包含业务流程组件</td></tr><tr><td>接受代价</td><td>双层调试、第三方升级和适配层维护</td></tr><tr><td>退出路径</td><td>公司令牌和常用契约独立；记录内部 DOM 依赖为零目标</td></tr><tr><td>验证指标</td><td>覆盖率、无障碍缺陷、例外数、升级人天、包装 Props 数</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>关键组件连续无法满足无障碍或性能、品牌覆盖需要大量内部 DOM 选择器、版本支持落后框架超过六个月、适配层代码接近第三方封装规模，或组织具备长期基础组件团队时复查。复查可以只替换某类组件，不必一次迁移全部。</p>',36)])])}const _=a(i,[["render",o]]);export{u as __pageData,_ as default};
